(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zzi-sj-prepa-ssrpf-j7-sf3"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zzi-sj-prepa-ssrpf-j7-sf3\",\n \"titre\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 56,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n   \"sha256\": \"c1e8c2d8402d3b954a7c6fc159ceb6b02b83cb88c53adce6ddd9268aa4b95034\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J SSR / PF · Prépa D.E J7 (SF3) · reprend en grande partie le J4 + nouvelles questions\",\n     \"slug\": \"prepa-ssrpf-j7-sf3\",\n     \"pages\": \"\",\n     \"count\": 56,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"SSR / PF\",\n     \"source\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__0\",\n       \"num\": \"1\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une patiente allaite exclusivement son nouveau-né âgé de 18 jours. Elle souhaite débuter une contraception œstro-progestative combinée car elle craint les autres méthodes. À ce stade l'OMS préconise la catégorie 3.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Chez la femme qui allaite exclusivement avant 6 semaines (moins de 42 jours, ici 18 jours) du post-partum, la contraception œstro-progestative combinée (COC) est classée en catégorie 4 (contre-indication absolue) selon les critères d'éligibilité médicale de l'OMS, et non en catégorie 3, car les œstrogènes réduisent le volume et la qualité du lait maternel.\\n\\nSource : Cours de Gynéco-Obstétrique L1/L3 — Le suivi post-natal (CPoN), p. 88-89 ; Cours SSR-PF — Planification familiale du post-partum.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__1\",\n       \"num\": \"2\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les pilules de quatrième génération contiennent du DIENOGEST\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les contraceptifs oraux combinés de quatrième génération associent de l'éthinylestradiol (ou de l'estradiol) à des progestatifs récents tels que la drospirénone, le diénogest, le nomégestrol ou la chlormadinone. Explication hors cours du projet (pharmacologie des contraceptifs hormonaux combinés).\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__2\",\n       \"num\": \"3\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"On parle de génération des contraceptifs hormonaux combinés selon le type de progestérone utilisée.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La classification par génération (1re, 2e, 3e et 4e générations) des contraceptifs hormonaux combinés dépend de la nature du progestatif (progestérone de synthèse) associé à l'œstrogène dans la formulation. Explication hors cours du projet.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__3\",\n       \"num\": \"4\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le préservatif, la cape cervicale, le spermicide et le diaphragme sont des méthodes de barrières\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les méthodes contraceptives de barrière empêchent la rencontre entre les spermatozoïdes et l'ovule ; elles regroupent les barrières mécaniques (préservatifs masculin et féminin, diaphragme, cape cervicale) et les barrières chimiques (spermicides).\\n\\nSource : Cours SSR-PF — Méthodes contraceptives de barrière.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__4\",\n       \"num\": \"5\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La palpation du sein se fait en position couchée, le bras du sein examiné replié sur la tête\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Lors de l'examen clinique des seins en consultation de planification familiale ou gynécologique, la palpation s'effectue sur une patiente en décubitus dorsal avec le bras du côté examiné relevé et replié sous/sur la tête afin d'étaler la glande mammaire sur la paroi thoracique.\\n\\nSource : Cours de Gynéco-Obstétrique — Examen clinique des seins.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__5\",\n       \"num\": \"6\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Mme KY désire avoir des rapports sexuels non protégés avec son conjoint après la pose d'implant. Alors, elle ne doit pas attendre 24 heures pour tout rapport sexuel après la pose.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Lorsque l'implant sous-cutané est inséré dans les délais recommandés (notamment dans les 7 premiers jours du cycle menstruel ou en relais immédiat d'une contraception hormonale active), l'effet contraceptif est immédiat ; il n'est pas nécessaire d'attendre 24 heures ni d'utiliser une méthode d'appoint.\\n\\nSource : Cours SSR-PF — Contraception par implants sous-cutanés.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__6\",\n       \"num\": \"7\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le counseling se définit comme étant un entretien, une tête à tête qui a lieu dans un endroit calme au cours duquel une personne aide une autre personne à trouver et choisir une solution à son problème.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « FAUX » pour cette formulation, distinguant le counseling en planification familiale (communication interpersonnelle structurée selon l'approche BERCER permettant un choix libre et éclairé d'une méthode contraceptive) d'un simple entretien généraliste.\\n\\nSource : Cours SSR-PF — Le counseling en planification familiale.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__7\",\n       \"num\": \"8\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La consultation en planification familiale est le processus par lequel un prestataire de services de planification familiale interagit avec un client pour choisir et utiliser une méthode contraceptive ou pour trouver une solution à un problème de santé sexuelle\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Cette définition correspond au counseling en planification familiale (interaction entre le prestataire et le client pour un choix libre et éclairé), et non à l'ensemble de la consultation médicale de PF qui comprend l'accueil, l'interrogatoire, l'examen clinique et la prestation.\\n\\nSource : Cours SSR-PF — Consultation et counseling en planification familiale.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__8\",\n       \"num\": \"9\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Mme RIA Sage-femme réfère une cliente qui présente un avortement provoqué septique avec un désir de contraception le DIU.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'avortement septique est une contre-indication absolue (catégorie 4 de l'OMS) à la pose immédiate d'un DIU en raison du risque d'aggravation de l'infection pelvienne ; la sage-femme doit donc référer la cliente pour prise en charge de l'infection et réévaluation ultérieure.\\n\\nSource : Cours SSR-PF — Critères d'éligibilité médicale du DIU et soins après avortement (SAA).\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__9\",\n       \"num\": \"10\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'examen des seins se fait méthodiquement quadrant par quadrant.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'inspection et la palpation des deux seins doivent se faire de façon méthodique, quadrant par quadrant (supéro-externe, inféro-externe, inféro-interne, supéro-interne), complétées par l'examen du mamelon et des aires ganglionnaires satellites.\\n\\nSource : Cours de Gynéco-Obstétrique — Suivi post-natal (CPoN), IV-2.4 :3, p. 85.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__10\",\n       \"num\": \"11\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les autres antécédents sont constitués des antécédents gynécologiques, obstétricaux et familiaux.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Dans l'observation clinique en PF/gynécologie, les antécédents sont classés en antécédents médicaux, chirurgicaux, gynécologiques, obstétricaux et familiaux ; les « autres antécédents » (ou mode de vie/allergies) ne regroupent pas les antécédents gynécologiques, obstétricaux et familiaux qui constituent des rubriques distinctes.\\n\\nSource : Cours SSR-PF — Fiche de consultation en planification familiale.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__11\",\n       \"num\": \"12\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'échographie est indiquée lorsque survient une infection après la pose d'un DIU.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"En cas d'infection pelvienne survenant sous DIU, le diagnostic est clinique et bactériologique, et la conduite repose sur l'antibiothérapie (et le retrait du DIU si absence d'amélioration sous 48-72 h) ; l'échographie est surtout indiquée lorsque les fils du DIU ne sont pas visibles à l'examen au spéculum.\\n\\nSource : Cours SSR-PF — Gestion des complications et effets secondaires du DIU.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__12\",\n       \"num\": \"13\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une patiente oublie deux pilules œstro-progestatives consécutives (jours dix-huit et dix-neuf de sa plaquette de vingt-un comprimés). Elle a eu un rapport non protégé au seizième jour du cycle. Il faut jeter les comprimés restants de la période d'arrêt et enchaîner sans pause.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Lorsqu'un oubli de 2 pilules actives survient au cours de la 3e semaine (jours 15 à 21) d'une plaquette de 21 comprimés, la patiente doit prendre la pilule oubliée la plus récente, finir les comprimés actifs restants, supprimer la semaine d'arrêt (ou jeter les comprimés inactifs) et enchaîner directement avec une nouvelle plaquette.\\n\\nSource : Cours SSR-PF — Conduite à tenir devant un oubli de pilule œstro-progestative combinée.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__13\",\n       \"num\": \"14\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le DIU entraîne les infections.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le DIU en lui-même ne provoque pas d'infection génitale haute ; le risque infectieux est uniquement lié à une contamination ascendante lors de la pose (non-respect de l'asepsie ou présence d'une cervicite/IST non dépistée au moment de l'insertion).\\n\\nSource : Cours SSR-PF — Dispositif intra-utérin (DIU) : idées reçues et prévention des infections.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__14\",\n       \"num\": \"15\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La pose du DIU est indiquée si à l'examen vous constatez un col sain.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'examen au spéculum avant l'insertion d'un DIU vérifie l'intégrité et la propreté du col utérin ; un col sain, sans cervicite purulente ni lésion suspecte, autorise la pose du DIU en l'absence de grossesse et d'autres contre-indications.\\n\\nSource : Cours SSR-PF — Technique d'insertion du DIU d'intervalle.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__15\",\n       \"num\": \"16\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le premier volet de la fiche de référence et contre-référence est rempli par le médecin.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le premier volet de la fiche de référence et contre-référence est rempli par le prestataire qui réfère (l'infirmier ou la sage-femme du centre périphérique) avant l'évacuation de la patiente ; le médecin de la structure d'accueil remplit le volet de contre-référence.\\n\\nSource : Cours de Soins Obstétricaux L2 — Organisation de la référence, p. 113.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__16\",\n       \"num\": \"17\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"En quoi consiste principalement une approche « transformatrice de genre » appliquée à la GHM en milieu scolaire ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Réserver l'enseignement de l'hygiène menstruelle exclusivement aux enseignants de mathématiques.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Déconstruire les tabous culturels en éduquant l'ensemble de la communauté scolaire.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Interdire strictement aux élèves de prononcer le mot « règles » dans l'enceinte de l'établissement.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Limiter l'accès aux toilettes propres uniquement aux élèves ayant les meilleures notes académiques.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Déconstruire les tabous culturels en éduquant l'ensemble de la communauté scolaire.\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'approche transformatrice de genre en gestion de l'hygiène menstruelle (GHM) vise à lever la stigmatisation et les tabous liés aux menstruations en impliquant et en éduquant toute la communauté éducative (filles, garçons, enseignants et parents).\\n\\nSource : Cours SSR-PF — Genre et santé de la reproduction des adolescents et jeunes (SRAJ).\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__17\",\n       \"num\": \"18\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Cocher le principe de base du counseling chez le client\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La liberté de la méthode contraceptive\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La liberté de s'éclairé\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le consentement exprimé\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Les droits du client\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Le consentement exprimé\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Du côté du client, le counseling repose sur le libre arbitre et le consentement éclairé et exprimé après réception d'informations complètes sur les méthodes disponibles.\\n\\nSource : Cours SSR-PF — Principes du counseling en planification familiale.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__18\",\n       \"num\": \"19\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une patiente de 29 ans fait retirer son implant à l'étonogestrel car elle souhaite planifier une grossesse avec son conjoint. Elle s'inquiète du temps nécessaire pour retrouver une fertilité normale. Que lui indiquez-vous ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"6 à 12 mois\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Immédiat\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"2 ans\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"3 cycles\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Immédiat\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Contrairement aux injectables progestatifs (qui peuvent entraîner un délai de 6 à 12 mois), le retour à la fertilité après le retrait d'un implant contraceptif (étonogestrel ou lévonorgestrel) est immédiat dès la disparition de l'hormone circulante.\\n\\nSource : Cours SSR-PF — Avantages et retour de la fécondité des implants contraceptifs.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__19\",\n       \"num\": \"20\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Cocher le principe de base du counseling chez le prestataire\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La maîtrise du débat\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le fait de tirer les leçons de l'exemple\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Demeurer positif, constructif\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'éducation du passé\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Demeurer positif, constructif\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Dans la relation d'aide, le prestataire doit adopter une attitude empathique, sans jugement, en demeurant positif et constructif afin de mettre le client en confiance et faciliter son expression.\\n\\nSource : Cours SSR-PF — Qualités et principes du conseiller en PF.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__20\",\n       \"num\": \"21\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quelle affirmation concernant la contraception d'urgence hormonale chez l'adolescente est exacte ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Elle peut remplacer une contraception régulière et être utilisée toutes les semaines sans risque.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Elle nécessite obligatoirement une prescription médicale préalable par un spécialiste.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Elle provoque systématiquement une interruption médicale de grossesse en cas d'œuf déjà implanté.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Elle doit être administrée le plus tôt possible après le rapport non protégé\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Elle doit être administrée le plus tôt possible après le rapport non protégé\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"L'efficacité de la contraception d'urgence hormonale (pilule du lendemain) est d'autant plus élevée qu'elle est prise précocement après le rapport sexuel non protégé (idéalement dans les 12 à 24 premières heures, et jusqu'à 72 à 120 heures selon la molécule). Elle n'est pas abortive et ne remplace pas une méthode régulière.\\n\\nSource : Cours SSR-PF — Contraception d'urgence et SRAJ.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__21\",\n       \"num\": \"22\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Nommer la phase du counseling où toutes les méthodes sont décrites\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Counseling initial\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"c) Counseling de suivi\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Counseling spécifique à la méthode\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Counseling initial\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le counseling initial (ou général) permet de présenter brièvement l'ensemble de la gamme des méthodes contraceptives disponibles afin que le client puisse orienter son choix, avant d'approfondir la méthode retenue lors du counseling spécifique.\\n\\nSource : Cours SSR-PF — Les trois phases du counseling en planification familiale.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__22\",\n       \"num\": \"23\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Cocher les deux étapes du counseling qui se suivent\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Rendez-vous\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"c) Renseignements\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Choix de méthode\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Explication\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. c) Renseignements ; C. Choix de méthode\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"Selon l'acronyme BERCER (Bienvenue, Entretien, Renseignements, Choix de la méthode, Explication, Rendez-vous), l'étape « Renseignements » (R) est immédiatement suivie de l'étape « Choix de la méthode » (C).\\n\\nSource : Cours SSR-PF — Les 6 étapes du counseling (approche BERCER).\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__23\",\n       \"num\": \"24\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une patiente de 39 ans, en bonne santé par ailleurs, souhaite débuter une pilule œstroprogestative combinée. Elle fume activement 18 cigarettes par jour depuis l'âge de vingt ans. Quelle est la conduite à tenir selon l'OMS ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Prescription possible sous surveillance tensionnelle rapprochée.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Prescription autorisée si la patiente s'engage à réduire sa consommation de moitié.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Contre-indication absolue.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Utilisation sans restriction\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Contre-indication absolue.\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Selon les critères d'éligibilité médicale de l'OMS, chez une femme âgée de 35 ans ou plus fumant au moins 15 cigarettes par jour (ici 39 ans et 18 cigarettes/jour), les contraceptifs œstro-progestatifs combinés sont classés en catégorie 4 (contre-indication absolue) en raison du risque cardiovasculaire majeur.\\n\\nSource : Cours SSR-PF — Critères d'éligibilité médicale de l'OMS (CHC).\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__24\",\n       \"num\": \"25\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Cocher le but de la consultation en planification familiale\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Ne pas s'assurer que la cliente est enceinte\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Dépister les infections sexuelles\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Identifier les indications médicales\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Identifier les indications médicales\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La consultation médicale de PF a pour but d'évaluer l'état de santé de la cliente, d'éliminer une grossesse en cours et d'identifier les indications et éventuelles contre-indications médicales aux différentes méthodes contraceptives.\\n\\nSource : Cours SSR-PF — Objectifs de la consultation de planification familiale.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__25\",\n       \"num\": \"26\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Il existe combien de groupes de contraceptifs hormonaux combinés\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"03\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"b) 04\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"c) 10\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"14\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. b) 04\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les contraceptifs hormonaux combinés (CHC) regroupent 4 formes galéniques ou groupes : les contraceptifs oraux combinés (COC), les contraceptifs injectables combinés (CIC), le patch contraceptif transdermique et l'anneau vaginal combiné.\\n\\nSource : Cours SSR-PF — Les contraceptifs hormonaux combinés (CHC).\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__26\",\n       \"num\": \"27\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Mme GRO est sous contraceptif injectable contenant deux types d'hormones. Cocher le prochain rendez-vous.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Rendez-vous dans quatre semaines\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Rendez-vous dans huit semaines\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Rendez-vous dans douze semaines\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Rendez-vous dans quatre semaines\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Un contraceptif injectable contenant deux hormones (œstrogène + progestatif) est un contraceptif injectable combiné (CIC, ex. Cyclofem, Mesigyna), dont l'administration est mensuelle : le rendez-vous suivant se fixe donc à 4 semaines (1 mois). Les délais de 8 et 12 semaines concernent respectivement le Noristerat et le Depo-Provera (progestatifs seuls).\\n\\nSource : Cours SSR-PF — Les contraceptifs injectables (CIC et CIP).\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__27\",\n       \"num\": \"28\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Cocher l'élément de l'identité du client dans la consultation en planification familiale\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Age en mois\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"b) Niveau d'éducation\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"c) Fonction\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. c) Fonction\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"L'identité du client dans le dossier de consultation en PF comprend le nom, les prénoms, l'âge (en années), le sexe, l'adresse, la situation matrimoniale et la profession/fonction.\\n\\nSource : Cours SSR-PF — Structure de l'observation clinique en PF.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__28\",\n       \"num\": \"29\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une patiente de 32 ans, tabagique sevrée, consulte pour une contraception hormonale combinée. Elle présente des migraines avec aura survenant deux fois par mois. Selon les critères d'éligibilité médicale de l'OMS, quelle est la classification de la CHC pour cette patiente ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Catégorie 1\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Catégorie 4\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Catégorie 2\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Catégorie 3\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Catégorie 4\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La migraine avec aura, quel que soit l'âge de la patiente, constitue une contre-indication absolue (catégorie 4 de l'OMS) à l'utilisation des contraceptifs hormonaux combinés (CHC) en raison du risque accru d'accident vasculaire cérébral ischémique.\\n\\nSource : Cours SSR-PF — Critères d'éligibilité médicale de l'OMS (CHC et céphalées/migraines).\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__29\",\n       \"num\": \"30\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La méthode contraceptive spécifique pour l'adolescent est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"MAMA\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Condom\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"c) Méthode chirurgicale volontaire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Condom\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le préservatif (condom) est la méthode de référence recommandée chez l'adolescent car il offre une double protection : prévention des grossesses non désirées et protection contre les IST/VIH-sida.\\n\\nSource : Cours SSR-PF — Contraception chez les adolescents et jeunes.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__30\",\n       \"num\": \"31\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Cocher l'élément qui figure sur la fiche de référence et contre-référence.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La date\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"c) La conduite à tenir infirmière\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le nom et la signature\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Le nom et la signature\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La fiche de référence et contre-référence doit obligatoirement comporter l'identification, le nom, la qualification et la signature du prestataire qui adresse la patiente afin d'authentifier l'acte de référence.\\n\\nSource : Cours de Soins Obstétricaux L2 — Organisation de la référence, p. 113.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__31\",\n       \"num\": \"32\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS : Une utilisatrice d'une pilule œstro-progestative monophasique oublie de prendre sa pilule du troisième jour de sa plaquette. Elle s'en aperçoit trente-six heures plus tard (au moment de prendre la pilule suivante). Elle a eu un rapport sexuel non protégé 48 heures avant l'oubli.\",\n       \"text\": \"Quelle est la conduite immédiate à tenir ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Prendre immédiatement la pilule oubliée.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Jeter la plaquette en cours et recommencer un nouveau cycle immédiatement\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Ne rien faire de particulier\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Attendre les prochaines règles.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Prendre immédiatement la pilule oubliée.\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Devant un oubli de plus de 12 heures (ici 36 heures) en 1re semaine de plaquette, le premier réflexe est de prendre immédiatement le comprimé oublié (même si cela implique de prendre 2 comprimés le même jour : celui oublié et celui du jour à l'heure habituelle).\\n\\nSource : Cours SSR-PF — Conduite à tenir en cas d'oubli de pilule combinée.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__32\",\n       \"num\": \"33\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS : Une utilisatrice d'une pilule œstro-progestative monophasique oublie de prendre sa pilule du troisième jour de sa plaquette. Elle s'en aperçoit trente-six heures plus tard (au moment de prendre la pilule suivante). Elle a eu un rapport sexuel non protégé 48 heures avant l'oubli.\",\n       \"text\": \"Doit-elle continuer la plaquette ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"OUI\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"NON\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. OUI\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Après avoir rattrapé le comprimé oublié, la patiente doit poursuivre la prise quotidienne des comprimés restants de sa plaquette à l'heure habituelle jusqu'à la fin.\\n\\nSource : Cours SSR-PF — Conduite à tenir en cas d'oubli de pilule combinée.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__33\",\n       \"num\": \"34\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS : Une utilisatrice d'une pilule œstro-progestative monophasique oublie de prendre sa pilule du troisième jour de sa plaquette. Elle s'en aperçoit trente-six heures plus tard (au moment de prendre la pilule suivante). Elle a eu un rapport sexuel non protégé 48 heures avant l'oubli.\",\n       \"text\": \"Doit-elle utiliser une contraception d'urgence ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"OUI\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"NON\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. OUI\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'oubli supérieur à 12 heures survient durant la 1re semaine de la plaquette (jour 3) et la patiente a eu un rapport sexuel non protégé dans les 5 jours précédant l'oubli (48 heures avant), ce qui expose à un risque élevé d'ovulation et justifie le recours à une contraception d'urgence.\\n\\nSource : Cours SSR-PF — Oubli de pilule combinée en 1re semaine et contraception d'urgence.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__34\",\n       \"num\": \"35\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS : Une utilisatrice d'une pilule œstro-progestative monophasique oublie de prendre sa pilule du troisième jour de sa plaquette. Elle s'en aperçoit trente-six heures plus tard (au moment de prendre la pilule suivante). Elle a eu un rapport sexuel non protégé 48 heures avant l'oubli.\",\n       \"text\": \"En cas de rapports sexuels doit-elle se protéger ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"OUI\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"NON\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. OUI\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"En raison de la baisse transitoire de la protection contraceptive liée à l'oubli de plus de 12 heures, elle doit utiliser une méthode barrière (préservatif) ou s'abstenir de rapports sexuels pendant les 7 jours suivants.\\n\\nSource : Cours SSR-PF — Oubli de pilule combinée et méthode d'appoint.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__35\",\n       \"num\": \"36\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une utilisatrice sous COC qui présente des spottings après trois cycles doit être :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Rassurer.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"b) Examiner\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"c) Référer\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. b) Examiner\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les saignements intermenstruels légers (spottings) sont fréquents et bénins durant les 3 premiers cycles d'adaptation sous COC (on rassure) ; s'ils persistent au-delà de 3 cycles, il faut examiner la cliente pour éliminer un oubli de pilule, une infection génitale ou une lésion cervicale.\\n\\nSource : Cours SSR-PF — Suivi et gestion des effets secondaires des COC.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__36\",\n       \"num\": \"37\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'examen gynécologique anormal chez une cliente sous contraception hormonale. Il faut :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Rassurer\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"b) Consultation prénatale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Référer\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Référer\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La découverte d'une anomalie lors de l'examen gynécologique (lésion suspecte du col, masse pelvienne, saignement inexpliqué) impose d'orienter et référer la cliente vers un médecin spécialiste pour investigation diagnostique.\\n\\nSource : Cours SSR-PF — Conduite à tenir lors de la visite de suivi en PF.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__37\",\n       \"num\": \"38\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Devant la présence d'autres signes de grossesse chez une cliente après la troisième plaquette\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Rassurer\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Examiner\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"b) c) Référer\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Examiner\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Devant des signes sympathiques de grossesse (nausées, tension mammaire, aménorrhée), il convient d'examiner la patiente et de réaliser un test de grossesse afin de confirmer ou d'infirmer une grossesse débutante avant toute décision d'arrêt ou de poursuite de la méthode.\\n\\nSource : Cours SSR-PF — Suivi des utilisatrices de contraceptifs oraux.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__38\",\n       \"num\": \"39\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le STEDIRIL contient :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"35 microgrammes EE\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"50 microgrammes EE\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"100 microgrammes EE\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 50 microgrammes EE\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le Stédiril® est une pilule œstro-progestative normodosée (de 2e génération) associant 50 microgrammes (0,05 mg) d'éthinylestradiol (EE) et 0,5 mg de norgestrel.\\n\\nSource : Cours SSR-PF — Classification et dosage des pilules œstro-progestatives combinées.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__39\",\n       \"num\": \"40\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une patiente sous pilule œstro-progestative souhaite passer à un implant sous-cutané. Elle a pris sa dernière pilule active hier et souhaite se faire poser l'implant aujourd'hui. Le prestataire :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La rassure.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Lui dit d'attendre les règles.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Elle doit revenir dans sept jours.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Elle utilise une protection par préservatif.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. La rassure.\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Lorsqu'une patiente utilise correctement une pilule œstro-progestative et a pris un comprimé actif la veille, la pose de l'implant peut se faire immédiatement sans attendre les prochaines règles ; le prestataire la rassure et procède à la pose.\\n\\nSource : Cours SSR-PF — Changement de méthode contraceptive (passage des COC à l'implant).\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__40\",\n       \"num\": \"41\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La patiente est-elle protégée ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"OUI\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"NON\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. OUI\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le relais étant effectué directement après la prise d'une pilule active sans intervalle libre, l'inhibition de l'ovulation est maintenue et la patiente reste protégée de façon continue.\\n\\nSource : Cours SSR-PF — Relais contraceptif vers l'implant sous-cutané.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__41\",\n       \"num\": \"42\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le prestataire doit-il insérer l'implant ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"OUI\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"NON\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. OUI\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La patiente n'étant pas enceinte (sous contraception orale active prise la veille), l'implant peut être inséré le jour même de la consultation après vérification de l'absence de contre-indication.\\n\\nSource : Cours SSR-PF — Moment d'insertion de l'implant contraceptif.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__42\",\n       \"num\": \"43\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La patiente est-elle protégée ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"OUI\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"NON\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. OUI\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La pose immédiate en relais d'une pilule active garantit une efficacité contraceptive immédiate sans besoin de méthode d'appoint. Remarque : question en double avec la question 41 dans le sujet.\\n\\nSource : Cours SSR-PF — Relais contraceptif vers l'implant sous-cutané.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__43\",\n       \"num\": \"44\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Mme HI a opté le 01 janvier 2025 pour les Comprimés combinés. Elle a oublié la prise du 01 mars et a néanmoins continué sa méthode.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Protégée\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"b) Non protégée\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"c) Référer\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Protégée\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Selon la correction nationale de la Prépa DE (les J), l'oubli isolé d'un seul comprimé combiné suivi de la poursuite régulière de la plaquette maintient l'efficacité contraceptive (« Protégée »), contrairement à l'oubli de deux comprimés ou plus.\\n\\nSource : Cours SSR-PF — Gestion de l'oubli d'un comprimé combiné.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__44\",\n       \"num\": \"45\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Mme HI exige les préservatifs pendant les rapports sexuels avec son conjoint.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Normal\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Anormal\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Anormal\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Anormal » : dans le contexte de cette étude de cas (où Mme HI est déjà sous contraception orale efficace et sans mention d'oubli multiple ni de risque d'IST), l'exigence systématique du préservatif en l'absence d'indication de double protection est jugée inhabituelle.\\n\\nSource : Cours SSR-PF — Suivi d'une cliente sous contraception orale.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__45\",\n       \"num\": \"46\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"29 mars 2025 Mme HI est sous contraceptif injectable progestatif. Car, elle a des migraines\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La décision est normale\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La décision est anormale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La décision n'est pas rassurante\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. La décision est normale\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Chez une patiente migraineuse, les œstrogènes sont contre-indiqués en raison du risque vasculaire ; le passage à un contraceptif injectable progestatif seul (CIP, dépourvu d'œstrogènes) est donc une décision médicale tout à fait appropriée et normale.\\n\\nSource : Cours SSR-PF — Critères d'éligibilité médicale de l'OMS (CIP et migraines).\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__46\",\n       \"num\": \"47\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"07 juin 2025, Mme HI opte pour les Comprimés. Car, elle a manifesté une rougeur au point d'injection. La PI est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Accompli\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Rigoureuse\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"b) c) Partielle\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. b) c) Partielle\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Une simple rougeur locale au point d'injection est un effet secondaire mineur et bénin qui ne justifie pas l'abandon de la méthode si la cliente est correctement rassurée et informée ; le changement de méthode traduit ici une prise en charge ou information (PI) partielle.\\n\\nSource : Cours SSR-PF — Gestion des effets secondaires mineurs des contraceptifs injectables.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__47\",\n       \"num\": \"48\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Mme HI peut utiliser en 2026\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Contraception chirurgical volontaire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"MAMA\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Dispositif intra utérin\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Dispositif intra utérin\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"En dehors d'un accouchement récent avec allaitement exclusif (MAMA) et s'agissant d'une méthode réversible de longue durée sans hormones ni œstrogènes (adaptée à ses antécédents de migraines), le dispositif intra-utérin (DIU) au cuivre constitue un choix parfaitement indiqué.\\n\\nSource : Cours SSR-PF — Indications du dispositif intra-utérin (DIU).\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__48\",\n       \"num\": \"49\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans quelle situation exceptionnelle le professionnel de santé est-il éthiquement et légalement amené à lever le secret médical concernant un(e) adolescent(e) ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Chaque fois que l'adolescent a une activité sexuelle avant 18 ans.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"En cas de danger immédiat pour la sécurité ou l'intégrité physique ou psychologique du mineur.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Lorsque les parents exigent de connaître le motif exact de la consultation.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Dès que l'adolescent refuse de dire ce qu'il a fait le week-end.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. En cas de danger immédiat pour la sécurité ou l'intégrité physique ou psychologique du mineur.\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le droit à la confidentialité s'applique pleinement aux adolescents en matière de santé sexuelle et reproductive ; la levée du secret professionnel n'est autorisée qu'à titre exceptionnel lorsqu'il existe un danger grave et imminent pour la sécurité ou l'intégrité physique ou psychologique du mineur (abus, violences, risque suicidaire).\\n\\nSource : Cours SSR-PF — Éthique, confidentialité et droits en santé de la reproduction des adolescents.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__49\",\n       \"num\": \"50\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'outil de travail en planification familiale\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le carnet de commande\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"b) Les fiches\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"c) La carte\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. b) Les fiches\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les fiches techniques et fiches de consultation/suivi (ainsi que la boîte à images) constituent les outils de travail quotidiens du prestataire lors de l'offre de services de planification familiale, tandis que le carnet de commande est un outil de gestion logistique.\\n\\nSource : Cours SSR-PF — Outils de prestation et de gestion en planification familiale.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__50\",\n       \"num\": \"51\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la méthode de BILLINGS, après l'ovulation la couleur de la glaire cervicale est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Trouble\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Mitigée\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Mélangée\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"d) Claire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Trouble\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Dans la méthode de l'ovulation (Billings), la glaire cervicale est claire, abondante, filante et transparente (aspect blanc d'œuf cru) juste avant et pendant l'ovulation sous l'effet des œstrogènes ; après l'ovulation, sous l'action de la progestérone, elle devient rare, épaisse, collante et trouble.\\n\\nSource : Cours SSR-PF — Méthodes naturelles basées sur la connaissance de la fécondité (méthode de Billings).\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__51\",\n       \"num\": \"52\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Cocher deux caractéristiques différenciant le CIC de Sayana Press :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Contraceptif\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"c) Progestérone\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"d) Intra dermique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Sous cutané\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"e) Intra musculaire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"D. Sous cutané ; E. e) Intra musculaire\",\n       \"answerLetters\": [\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"Le Sayana Press (DMPA-SC) s'administre par voie sous-cutanée (SC), tandis que les contraceptifs injectables combinés (CIC) s'administrent par voie intramusculaire (IM) ; leurs voies d'administration respectives (sous-cutanée vs intramusculaire) constituent deux caractéristiques majeures qui les différencient.\\n\\nSource : Cours SSR-PF — Contraceptifs injectables (CIC et Sayana Press).\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__52\",\n       \"num\": \"53\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'implant est contre-indiqué chez :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La paucipare\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"b) La nullipare\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"c) La ménopausée\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. c) La ménopausée\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"L'implant contraceptif peut être utilisé sans restriction par la nullipare comme par la paucipare ; en revanche, chez la femme ménopausée confirmée, il n'y a plus de fonction ovarienne ovulatoire ni de besoin contraceptif, ce qui en fait une non-indication / contre-indication d'usage.\\n\\nSource : Cours SSR-PF — Indications et contre-indications des implants contraceptifs.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__53\",\n       \"num\": \"54\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS : Une patiente de 26 ans, porteuse d'un dispositif intra-utérin au lévonorgestrel depuis huit mois, consulte car elle n'a plus ses règles du tout depuis 4 mois. Elle s'inquiète d'une possible grossesse ou d'une pathologie.\",\n       \"text\": \"Quel est votre premier diagnostic ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Ménopause précoce iatrogène\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Echec de la contraception\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Aménorrhée\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"grossesse extra utérine\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Aménorrhée\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"L'aménorrhée secondaire est un effet secondaire fréquent, bénin et attendu du DIU hormonal au lévonorgestrel (SIU-LNG), dû à l'atrophie locale de l'endomètre sous l'action du progestatif, sans altération de la fertilité ultérieure.\\n\\nSource : Cours SSR-PF — Effets secondaires du DIU hormonal (lévonorgestrel).\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__54\",\n       \"num\": \"55\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS : Une patiente de 26 ans, porteuse d'un dispositif intra-utérin au lévonorgestrel depuis huit mois, consulte car elle n'a plus ses règles du tout depuis 4 mois. Elle s'inquiète d'une possible grossesse ou d'une pathologie.\",\n       \"text\": \"Quelle est l'attitude du prestataire face à la patiente ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Rassurer\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"d) Réaliser un curetage\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Retirer le dispositif intra utérin\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Rassurer\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Après avoir écarté une grossesse par l'interrogatoire et l'examen clinique (ou un test si nécessaire), le prestataire doit rassurer la patiente en lui expliquant que l'absence de règles sous DIU au lévonorgestrel est sans danger pour sa santé et ne nécessite pas le retrait du dispositif.\\n\\nSource : Cours SSR-PF — Conduite à tenir devant une aménorrhée sous contraceptif progestatif / SIU-LNG.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j7-sf3__55\",\n       \"num\": \"56\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Cochez la qualité morale d'un bon conseiller\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Comprend les avantages de toutes les méthodes contraceptives\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Comprend les facteurs qui influencent le choix d'une méthode\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Encourage le client à poser des questions\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Encourage le client à poser des questions\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Les propositions a et b relèvent des compétences techniques (savoirs) du prestataire, tandis qu'encourager le client à poser des questions relève des qualités relationnelles et morales (savoir-être : écoute active, empathie, ouverture) d'un bon conseiller.\\n\\nSource : Cours SSR-PF — Qualités d'un bon conseiller en planification familiale.\",\n       \"sourceDoc\": \"Préparation D.E (J) · SSR / PF · Prépa D.E J7 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
